import sys
print(sys.getrecursionlimit())  # 1000

def zaehle(n):
    if n == 0:
        return 0
    return 1 + zaehle(n - 1)

print(zaehle(500))   # 500

def zaehle(n):
    if n == 0:
        return 0
    return 1 + zaehle(n - 1)

try:
    zaehle(100000)
except RecursionError:
    print("Zu tief!")   # Zu tief!

def fak_end(n, acc=1):
    if n <= 1:
        return acc
    return fak_end(n - 1, acc * n)

print(fak_end(5))   # 120
# fak_end(5, 1) → fak_end(4, 5)
# → fak_end(3, 20) → fak_end(2, 60)
# → fak_end(1, 120) → 120

